// ---------- Demo ROM ----------
  // A simple program that draws a 4x4 sprite and moves it right when key 1 is pressed,
  // left when key 2 is pressed, up when key 3 is pressed, down when key 4 is pressed.
  // It also blinks using the delay timer.
  //
  // Program layout:
  // 0x200: 6000 LD V0, 0x00  ; V0 = x position (start at 0)
  // 0x202: 6100 LD V1, 0x00  ; V1 = y position (start at 0)
  // 0x204: 6200 LD V2, 0x04  ; V2 = sprite size (4)
  // 0x206: 6300 LD V3, 0x01  ; V3 = blink state
  // 0x208: 6400 LD V4, 0x00  ; V4 = delay counter
  // 0x20A: 00E0 CLS
